test("workspace view choices survive the compact workspace roundtrip",()=>{
  const raw=encodeWorkspace(payload({view:view()}));
  assert.deepEqual(parseWorkspacePayload(raw,{repositoryReferences:true}).view,view());
});

test("per-collection structure and connection choices survive a saved view",()=>{
  const collectionView={...view(),expandedCollectionIds:["urn:head","<_:stored-head>"],connectedCollectionIds:["urn:head"]};
  const original=payload({view:collectionView});
  original.graph.nodes.push({id:"urn:head",label:"List",kind:"iri"},{id:"<_:stored-head>",label:"List",kind:"blank"});
  const opened=parseWorkspacePayload(encodeWorkspace(original),{repositoryReferences:true});
  assert.deepEqual(opened.view,collectionView);
});

test("restored collection choices follow migrated blank nodes and drop missing heads",()=>{
  const original=payload({view:{...view(),expandedCollectionIds:["_:head","<_:fixed>","urn:gone"],
    connectedCollectionIds:["<_:fixed>","urn:gone"]}});
  original.graph.nodes.push({id:"_:head",label:"Legacy list",kind:"blank"},{id:"<_:fixed>",label:"Fixed list",kind:"blank"});
  for(const repositoryReferences of [true,false]){
    const restored=parseWorkspacePayload(JSON.stringify(original),{repositoryReferences});
    const [legacy,fixed]=restored.graph.nodes.slice(1).map(node=>node.id);
    assert.notEqual(legacy,"_:head");
    assert.deepEqual(restored.view.expandedCollectionIds,[legacy,fixed]);
    assert.deepEqual(restored.view.connectedCollectionIds,[fixed]);
  }
});

test("invalid collection view choices do not invalidate the saved RDF",()=>{
  for(const choices of [{expandedCollectionIds:[42]},{connectedCollectionIds:"urn:head"}]){
    const opened=parseWorkspacePayload(encodeWorkspace(payload({view:{...view(),...choices}})),{repositoryReferences:true});
    assert.equal(opened.view,undefined);
    assert.equal(opened.graph.nodes.length,1);
  }
});

test("every view mode the page has survives a save",()=>{
  for(const viewMode of VIEW_MODES){
    const raw=encodeWorkspace(payload({view:{...view(),viewMode}}));
    assert.equal(parseWorkspacePayload(raw,{repositoryReferences:true}).view?.viewMode,viewMode);
  }
});

test("whether a view followed the label preferences survives a save; views saved before keep their policy",()=>{
  for(const follows of [true,false]){
    const raw=encodeWorkspace(payload({view:{...view(),labelPolicyFollowsPreferences:follows}}));
    assert.equal(parseWorkspacePayload(raw,{repositoryReferences:true}).view?.labelPolicyFollowsPreferences,follows);
  }
  const older=parseWorkspacePayload(encodeWorkspace(payload({view:view()})),{repositoryReferences:true}).view;
  assert.equal("labelPolicyFollowsPreferences" in older,false);
});

test("a view this version cannot read is left out; the graph still opens and recovers",()=>{
  const unreadable=[{...view(),version:2},{...view(),viewMode:"list"},{...view(),panels:{}},
    {...view(),labelPolicy:{...view().labelPolicy,languages:["not a tag"]}},{...view(),labelPolicyFollowsPreferences:"yes"}];
  for(const candidate of unreadable){
    const raw=encodeWorkspace(payload({view:candidate}));
    const opened=parseWorkspacePayload(raw,{repositoryReferences:true});
    assert.ok(opened,`opens despite ${JSON.stringify(candidate).slice(0,60)}`);
    assert.equal(opened.view,undefined);
    assert.equal(opened.graph.nodes.length,1);
    assert.equal(recoverWorkspacePayload(raw)?.payload.graph.nodes.length,1);
  }
});

test("a named group none of whose nodes is in the graph is dropped when opened; an empty one stays",()=>{
  const raw=JSON.stringify(payload({namedGroups:[{id:"gone",name:"Gone",color:"red",nodeIds:["urn:missing"]},
    {id:"part",name:"Part",color:"blue",nodeIds:["urn:a","urn:missing"]},{id:"empty",name:"Empty",color:"green",nodeIds:[]}]}));
  assert.deepEqual(parseWorkspacePayload(raw,{repositoryReferences:true}).namedGroups.map(group=>[group.id,group.nodeIds]),
    [["part",["urn:a"]],["empty",[]]]);
});

test("old workspaces show the stored display preferences",()=>{
  const stored=new Map([[SHOW_VALUES_STORAGE_KEY,"true"],[SHOW_LABELS_STORAGE_KEY,"false"]]);
  assert.deepEqual(readDisplayPreferences({getItem:key=>stored.get(key)??null}),{showValues:true,showAllEdgeLabels:false});
  assert.deepEqual(readDisplayPreferences({getItem(){throw new Error("blocked");}}),{showValues:false,showAllEdgeLabels:false});
  assert.deepEqual(readDisplayPreferences(undefined),{showValues:false,showAllEdgeLabels:false});
});
